<?php
require_once 'config/layout.php';require_once 'config/guidance.php';require_once 'config/admin_helpers.php';
require_admin();$user=current_user();$error='';$message='';$allowed=['institutions','programmes','scholarships','career_catalogue'];
$type=is_string($_GET['type']??null)&&in_array($_GET['type'],$allowed,true)?$_GET['type']:'institutions';$editId=is_string($_GET['id']??null)?substr($_GET['id'],0,64):'';$payloadText='';
if($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf($_POST['csrf']??null);
 try {
  $action=input_text('action',40);
  if($action==='school') {
   admin_reauthenticate($user,input_text('admin_password',72));$name=input_text('school_name',150);$code=input_text('school_code',40);
   if(!$name||!preg_match('/^[A-Z0-9_-]{2,40}$/D',$code))throw new InvalidArgumentException('Use a school name and a unique uppercase school code.');
   db()->prepare('INSERT INTO schools(name,code) VALUES(?,?)')->execute([$name,$code]);audit_event('school_created','school',db()->lastInsertId());$message='School added.';
  } elseif($action==='user') {
   admin_reauthenticate($user,input_text('admin_password',72));$target=(int)($_POST['user_id']??0);$role=input_text('role',15);$school=(int)($_POST['school_id']??0);
   if($target===(int)$user['id'])throw new InvalidArgumentException('You cannot change your own role or school assignment.');
   if(!in_array($role,['learner','teacher'],true))throw new InvalidArgumentException('Administrator appointments require the trusted CLI tool.');
   db()->beginTransaction();$q=db()->prepare('SELECT id,role FROM users WHERE id=? FOR UPDATE');$q->execute([$target]);$old=$q->fetch();
   if(!$old)throw new InvalidArgumentException('User not found.');
   if($old['role']==='admin')throw new InvalidArgumentException('Administrator role changes require the trusted CLI tool, which protects the last administrator.');
   if($school){$q=db()->prepare('SELECT id FROM schools WHERE id=?');$q->execute([$school]);if(!$q->fetchColumn())throw new InvalidArgumentException('Select a registered school.');}
   db()->prepare('UPDATE users SET role=? WHERE id=?')->execute([$role,$target]);
   db()->prepare('INSERT INTO user_security(user_id,school_id,auth_version) VALUES(?,?,2) ON DUPLICATE KEY UPDATE school_id=VALUES(school_id),auth_version=auth_version+1')->execute([$target,$school?:null]);
   db()->prepare('UPDATE teacher_grants SET revoked_at=UTC_TIMESTAMP() WHERE (learner_id=? OR teacher_id=?) AND revoked_at IS NULL')->execute([$target,$target]);
   db()->prepare("UPDATE consent_records SET revoked_at=UTC_TIMESTAMP() WHERE revoked_at IS NULL AND ((user_id=? AND purpose LIKE 'teacher_access:%') OR purpose=?)")->execute([$target,'teacher_access:'.$target]);
   audit_event('role_school_updated','account',$target,['from_role'=>$old['role'],'to_role'=>$role,'school_id'=>$school?:null]);db()->commit();$message='Role and school updated. Existing sessions and guidance permissions were revoked.';
  } elseif($action==='submit') {
   $type=input_text('type',30);$payloadText=input_text('payload',48000);$payload=json_decode($payloadText,true,64,JSON_THROW_ON_ERROR);
   if(!is_array($payload))throw new InvalidArgumentException('Enter a JSON object.');$payload=validate_content_payload($type,$payload);
   db()->prepare('INSERT INTO content_submissions(entity_type,record_id,payload,submitted_by) VALUES(?,?,?,?)')->execute([$type,$payload['id'],json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$user['id']]);
   audit_event('content_submitted',$type,$payload['id']);$message='Draft submitted. Another administrator must review official evidence before publication.';
  } elseif($action==='review') {
   admin_reauthenticate($user,input_text('admin_password',72));$id=(int)($_POST['submission_id']??0);$decision=input_text('decision',10);$note=input_text('review_note',1000);
   if(!in_array($decision,['publish','reject'],true)||mb_strlen($note)<12)throw new InvalidArgumentException('Choose a decision and record a review note of at least 12 characters.');
   if($decision==='publish'&&empty($_POST['source_checked']))throw new InvalidArgumentException('Confirm that you checked the official source and the encoded requirements.');
   db()->beginTransaction();$q=db()->prepare('SELECT * FROM content_submissions WHERE id=? FOR UPDATE');$q->execute([$id]);$draft=$q->fetch();
   if(!$draft||$draft['status']!=='pending')throw new InvalidArgumentException('This draft is not awaiting review.');
   if((int)$draft['submitted_by']===(int)$user['id'])throw new InvalidArgumentException('A different administrator must review this draft.');
   if($decision==='publish') {$p=validate_content_payload($draft['entity_type'],json_decode($draft['payload'],true,64,JSON_THROW_ON_ERROR));publish_content($draft['entity_type'],$p);}
   db()->prepare('UPDATE content_submissions SET status=?,reviewed_by=?,review_note=?,reviewed_at=UTC_TIMESTAMP() WHERE id=?')->execute([$decision==='publish'?'published':'rejected',$user['id'],$note,$id]);
   audit_event('content_'.$decision,$draft['entity_type'],$draft['record_id'],['submission_id'=>$id]);db()->commit();$message=$decision==='publish'?'Verified content published.':'Draft rejected; the published record was unchanged.';
  } else throw new InvalidArgumentException('Unknown action.');
 } catch(InvalidArgumentException|JsonException $ex) {if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}
 catch(PDOException $ex){if(db()->inTransaction())db()->rollBack();error_log('Career Compass administrator database operation failed.');$error='The change could not be saved. Check for a duplicate school code or invalid reference.';}
}
if(!in_array($type,$allowed,true))$type='institutions';
if($editId&&!$payloadText){$q=db()->prepare('SELECT payload FROM '.$type.' WHERE id=?');$q->execute([$editId]);$raw=$q->fetchColumn();if($raw)$payloadText=json_encode(json_decode($raw,true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);}
if(!$payloadText)$payloadText=json_encode(['id'=>'new-record','name'=>'Institution name','official_url'=>'https://','source_url'=>'https://','source_document'=>'Official page or prospectus title','publication_year'=>null,'last_verified'=>gmdate('Y-m-d'),'verification_scope'=>'Describe facts checked and outstanding questions.','accreditation_status'=>'not_assessed'],JSON_PRETTY_PRINT);
$counts=[];foreach(['users','assessments','recommendation_runs','institutions','programmes','scholarships'] as $table)$counts[$table]=(int)db()->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();
$schools=db()->query('SELECT * FROM schools ORDER BY name')->fetchAll();$search=trim(is_string($_GET['user_search']??null)?substr($_GET['user_search'],0,120):'');
$q=db()->prepare('SELECT u.id,u.full_name,u.email,u.role,s.school_id,sc.name AS school_name FROM users u LEFT JOIN user_security s ON s.user_id=u.id LEFT JOIN schools sc ON sc.id=s.school_id WHERE u.email LIKE ? OR u.full_name LIKE ? ORDER BY u.id DESC LIMIT 50');$q->execute(['%'.$search.'%','%'.$search.'%']);$users=$q->fetchAll();
$records=db()->query('SELECT id,'.($type==='institutions'?'name':'title').' AS label,verification_status,last_verified FROM '.$type.' ORDER BY label LIMIT 200')->fetchAll();
$pending=db()->query("SELECT d.*,u.full_name AS author FROM content_submissions d LEFT JOIN users u ON u.id=d.submitted_by WHERE d.status='pending' ORDER BY d.id DESC LIMIT 50")->fetchAll();
$audit=db()->query('SELECT id,actor_id,event,target_type,target_id,created_at FROM audit_logs ORDER BY id DESC LIMIT 50')->fetchAll();
page_start('Administration','admin'); ?>
<main id="main" class="wide page-space"><div class="page-intro"><span class="eyebrow muted-eyebrow">SYSTEM ADMINISTRATION</span><h1>Content, access & system health</h1><p>Publish source-checked guidance with a second reviewer. School assignments control educator access; learner consent is still required.</p></div>
<?php if($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif; ?><?php if($message): ?><div class="alert success" role="status"><?= e($message) ?></div><?php endif; ?>
<div class="three-grid"><?php foreach($counts as $label=>$count): ?><div class="panel stat-card"><span><?= e(str_replace('_',' ',$label)) ?></span><strong><?= $count ?></strong></div><?php endforeach; ?></div>
<section class="panel"><h2>System health</h2><ul><li>Database: connected</li><li>Email transport: <?= mail_ready()?'Configured (delivery depends on server mail transport)':'Not configured; recovery and verification email unavailable' ?></li><li>Required email verification: <?= env_value('REQUIRE_EMAIL_VERIFICATION')==='1'?'Enabled':'Disabled' ?></li><li>Internal AI token: <?= env_value('INTERNAL_API_TOKEN')!==''?'Configured':'Not configured — local demonstration only' ?></li><li>HTTPS enforcement: <?= env_value('APP_FORCE_HTTPS')==='1'?'Enabled':'Disabled — local demonstration only' ?></li><li>Runtime: PHP <?= e(PHP_MAJOR_VERSION.'.'.PHP_MINOR_VERSION) ?></li></ul><p>Verify the recommendation service using the deployment health check. No credentials, database dumps or raw learner records are exposed here.</p><p>Back up using a restricted database operator account; encrypt backups outside the web root; test restoration in an isolated database; run additive migrations only after backup. Never copy a live database directory as a backup. Run <code>scripts/security_maintenance.php</code> for expired token and retention maintenance. Review <code>docs/SECURITY_DEPLOYMENT.md</code>.</p></section>
<section class="panel" id="content"><h2>Content catalogue</h2><form method="get" class="form-grid"><label>Content type<select name="type"><?php foreach($allowed as $option): ?><option value="<?= e($option) ?>" <?= $type===$option?'selected':'' ?>><?= e(str_replace('_',' ',$option)) ?></option><?php endforeach; ?></select></label><button class="btn btn-outline">Browse records</button></form><div class="table-wrap"><table><thead><tr><th>Record</th><th>Verification</th><th>Checked</th></tr></thead><tbody><?php foreach($records as $r): ?><tr><td><a href="admin.php?type=<?= e($type) ?>&amp;id=<?= rawurlencode($r['id']) ?>#edit-content"><?= e($r['label']) ?></a></td><td><?= e($r['verification_status']) ?></td><td><?= e($r['last_verified']??'Unknown') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel" id="edit-content"><h2>Submit a source-checked draft</h2><p>Select a record above to edit, or provide a new JSON record using the documented data schema. Publication needs another administrator. Use null for unknown dates and preserve unresolved admission conditions.</p><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="submit"><label>Content type<select name="type"><?php foreach($allowed as $option): ?><option value="<?= e($option) ?>" <?= $type===$option?'selected':'' ?>><?= e(str_replace('_',' ',$option)) ?></option><?php endforeach; ?></select></label><label>Record JSON<textarea name="payload" rows="18" maxlength="48000" spellcheck="false" required><?= e($payloadText) ?></textarea></label><button class="btn btn-primary">Submit for verification review</button></form></section>
<section class="panel"><h2>Pending verification reviews</h2><?php if(!$pending): ?><p>No content awaiting review.</p><?php endif; ?><?php foreach($pending as $draft): ?><article class="programme-item"><h3><?= e($draft['entity_type'].' / '.$draft['record_id']) ?></h3><p>Submitted by <?= e($draft['author']??'Former administrator') ?> on <?= e($draft['created_at']) ?></p><details><summary>Inspect proposed JSON and source evidence</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= e(json_encode(json_decode($draft['payload'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details><?php if((int)$draft['submitted_by']!==(int)$user['id']): ?><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="review"><input type="hidden" name="submission_id" value="<?= (int)$draft['id'] ?>"><label>Review decision<select name="decision"><option value="reject">Reject / request corrections</option><option value="publish">Publish verified content</option></select></label><label>Review notes<textarea name="review_note" minlength="12" maxlength="1000" required rows="3"></textarea></label><label class="check-label"><input type="checkbox" name="source_checked" value="1"><span>I checked the official source, verification scope and encoded admission rules. Unknown facts are clearly identified.</span></label><label>Your current password<input type="password" name="admin_password" autocomplete="current-password" maxlength="72" required></label><button class="btn btn-primary">Record review decision</button></form><?php else: ?><p>Awaiting another administrator. You cannot review your own draft.</p><?php endif; ?></article><?php endforeach; ?></section>
<section class="panel"><h2>Registered schools</h2><ul><?php foreach($schools as $s): ?><li><?= e($s['name'].' ('.$s['code'].')') ?></li><?php endforeach; ?></ul><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="school"><label>School name<input name="school_name" maxlength="150" required></label><label>Unique school code<input name="school_code" maxlength="40" pattern="[A-Z0-9_-]{2,40}" required></label><label>Your current password<input type="password" name="admin_password" autocomplete="current-password" maxlength="72" required></label><button class="btn btn-outline">Add school</button></form></section>
<section class="panel"><h2>User roles and school assignments</h2><p>Confirm educator identity and school membership before assigning access. Changing either revokes old guidance grants and sessions. Administrator appointments use the trusted CLI tool.</p><form method="get" class="career-search"><label for="user-search" class="visually-hidden">Find a user by name or email</label><input id="user-search" name="user_search" value="<?= e($search) ?>" maxlength="120" placeholder="Name or email"><button class="btn btn-outline">Find user</button></form><p>Showing at most 50 matching users.</p><?php foreach($users as $u): ?><details class="programme-item"><summary><?= e($u['full_name'].' · '.$u['role'].' · '.($u['school_name']??'No confirmed school')) ?></summary><p><?= e($u['email']) ?></p><?php if($u['role']!=='admin' && (int)$u['id']!==(int)$user['id']): ?><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="user"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><label>Role<select name="role"><option value="learner" <?= $u['role']==='learner'?'selected':'' ?>>Learner</option><option value="teacher" <?= $u['role']==='teacher'?'selected':'' ?>>Teacher / counsellor</option></select></label><label>Confirmed school<select name="school_id"><option value="0">Unassigned</option><?php foreach($schools as $s): ?><option value="<?= (int)$s['id'] ?>" <?= (int)$u['school_id']===(int)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select></label><label>Your current password<input type="password" name="admin_password" autocomplete="current-password" maxlength="72" required></label><button class="btn btn-primary">Update access assignment</button></form><?php endif; ?></details><?php endforeach; ?></section>
<section class="panel"><h2>Recent audit events</h2><p>Last 50 events; passwords, tokens, counselling text and marks are excluded.</p><div class="table-wrap"><table><thead><tr><th>Date (UTC)</th><th>Actor ID</th><th>Event</th><th>Target</th></tr></thead><tbody><?php foreach($audit as $a): ?><tr><td><?= e($a['created_at']) ?></td><td><?= e((string)($a['actor_id']??'Removed')) ?></td><td><?= e($a['event']) ?></td><td><?= e($a['target_type'].' '.($a['target_id']??'')) ?></td></tr><?php endforeach; ?></tbody></table></div></section></main>
